function mifflin(sex, kg, cm, age){ return 10*kg + 6.25*cm - 5*age + (sex==='m'?5:-161); }
function harris(sex, kg, cm, age){
  if(sex==='m') return 88.362 + 13.397*kg + 4.799*cm - 5.677*age;
  return 447.593 + 9.247*kg + 3.098*cm - 4.330*age;
}
var MULT={sedentary:1.2, light:1.375, moderate:1.55, active:1.725, athlete:1.9};
function tdee(bmr, act){ var k=MULT[act]||1.2; return bmr*k; }
function goalCalories(tdeeVal, goal){ // lose0.25/lose0.5/maintain/gain0.25/gain0.5 (kg/周)
  var d={'-0.5':-550,'-0.25':-275,'0':0,'0.25':275,'0.5':550}[goal]||0; return tdeeVal+d; }
var EXPORTS={mifflin:mifflin, harris:harris, MULT:MULT, tdee:tdee, goalCalories:goalCalories};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.TdeeForgePure = EXPORTS; }
